DROP TABLE invitation_schema;CREATE TABLE invitation_schema (singleton INTEGER PRIMARY KEY CHECK(singleton=1), version INTEGER NOT NULL CHECK(version=3)) STRICT;CREATE TRIGGER invitation_phone_rebind AFTER UPDATE OF token_digest ON invitation_phones BEGIN UPDATE invitation_consents SET enabled=0,generation=min(generation+1,9007199254740991),transport_phone_generation=0,transport_status='unavailable' WHERE phone_id=NEW.id AND user_id=NEW.user_id; END;ALTER TABLE invitation_broker_revocations RENAME TO invitation_broker_revocations_old;CREATE TABLE invitation_broker_revocations (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL, enrollment_id TEXT NOT NULL, generation INTEGER NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0) STRICT;INSERT INTO invitation_broker_revocations SELECT * FROM invitation_broker_revocations_old;DROP TABLE invitation_broker_revocations_old;CREATE TRIGGER invitation_consent_cleanup BEFORE DELETE ON invitation_consents WHEN OLD.broker_ticket IS NOT NULL BEGIN INSERT INTO invitation_broker_revocations(id,user_id,enrollment_id,generation,created_at,expires_at,attempts) VALUES(OLD.broker_ticket,OLD.user_id,CASE WHEN json_valid(OLD.broker_ticket) THEN coalesce(json_extract(OLD.broker_ticket,'$.ticket_id'),OLD.broker_ticket) ELSE OLD.broker_ticket END,OLD.transport_generation,0,9223372036854775807,0) ON CONFLICT(id) DO NOTHING; END;INSERT INTO invitation_schema VALUES(1,3);